  AutoScalingClient, AutoScalingServiceException, DescribeAutoScalingGroupsCommand,
  DetachInstancesCommand, SetDesiredCapacityCommand,
} from "@aws-sdk/client-auto-scaling";
import { CreateTagsCommand, DescribeInstancesCommand, EC2Client } from "@aws-sdk/client-ec2";
import { setTimeout as sleep } from "node:timers/promises";

export interface ClaimRequest { size: "lite" | "full" | "wide"; runId: string; agent: string; jiraKey: string | null; spot: boolean }
export interface Sandbox { instanceId: string; size: string; spot: boolean; runId: string }

const asg = new AutoScalingClient({ region: "us-east-1" });
const ec2 = new EC2Client({ region: "us-east-1" });

// Small helpers the ticket's sketch assumes. In ai-agents they live next to the activities.
const group = async (name: string) =>
  (await asg.send(new DescribeAutoScalingGroupsCommand({ AutoScalingGroupNames: [name] }))).AutoScalingGroups?.[0];
const desired = async (name: string) => (await group(name))?.DesiredCapacity ?? 0;
const inServiceIds = async (name: string) =>
  ((await group(name))?.Instances ?? []).filter((i) => i.LifecycleState === "InService").map((i) => i.InstanceId!);
const leaseUntil = ({ hours }: { hours: number }) => new Date(Date.now() + hours * 3_600_000).toISOString();
const findInstance = async (tags: Record<string, string>): Promise<Sandbox | null> => {
  const out = await ec2.send(new DescribeInstancesCommand({ Filters: [
    ...Object.entries(tags).map(([k, v]) => ({ Name: `tag:${k}`, Values: [v] })),
    { Name: "instance-state-name", Values: ["pending", "running", "stopping", "stopped"] },
  ] }));
  const inst = out.Reservations?.[0]?.Instances?.[0];
  if (!inst?.InstanceId) return null;
  const tag = (k: string) => inst.Tags?.find((t) => t.Key === k)?.Value ?? "";
  return { instanceId: inst.InstanceId, size: tag("ai-agents:size"), spot: inst.InstanceLifecycle === "spot", runId: tag("ai-agents:run-id") };
};

