import test, { beforeEach } from "node:test";
import assert from "node:assert/strict";
import { mockClient } from "aws-sdk-client-mock";
import { MockActivityEnvironment } from "@temporalio/testing";
import {
  AutoScalingClient, AutoScalingServiceException, DescribeAutoScalingGroupsCommand,
  DetachInstancesCommand, SetDesiredCapacityCommand,
} from "@aws-sdk/client-auto-scaling";
import { CreateTagsCommand, DescribeInstancesCommand, EC2Client } from "@aws-sdk/client-ec2";
import { acquireSandbox } from "../src/sandbox.js";

const asgMock = mockClient(AutoScalingClient);
const ec2Mock = mockClient(EC2Client);
const req = { size: "full" as const, runId: "run-1", agent: "nova", jiraKey: "RH-1234", spot: false };
const group = (desired: number, ...ids: string[]) => ({ AutoScalingGroups: [{ AutoScalingGroupName: "ai-agents-sandbox-full",
  MinSize: 0, MaxSize: 3, DesiredCapacity: desired, DefaultCooldown: 300, AvailabilityZones: [], HealthCheckType: "EC2", CreatedTime: new Date(),
  Instances: ids.map((InstanceId) => ({ InstanceId, LifecycleState: "InService" as const, AvailabilityZone: "us-east-1a", HealthStatus: "Healthy", ProtectedFromScaleIn: false })) }] });

beforeEach(() => { asgMock.reset(); ec2Mock.reset(); });

test("a claim raises desired by one, detaches the new VM and tags it", async () => {
  ec2Mock.on(DescribeInstancesCommand).resolves({ Reservations: [] });
  asgMock.on(DescribeAutoScalingGroupsCommand)
    .resolvesOnce(group(0)) // before: nothing in service
    .resolvesOnce(group(0)) // desired is 0
    .resolves(group(1, "i-new")); // the warm VM came up
  const vm = await new MockActivityEnvironment().run(acquireSandbox, req);
  assert.equal(vm.instanceId, "i-new");
  assert.equal(asgMock.commandCalls(SetDesiredCapacityCommand)[0]!.args[0].input.DesiredCapacity, 1);
  assert.equal(asgMock.commandCalls(DetachInstancesCommand)[0]!.args[0].input.ShouldDecrementDesiredCapacity, true);
  const tags = ec2Mock.commandCalls(CreateTagsCommand)[0]!.args[0].input.Tags!;
  assert.ok(tags.some((t) => t.Key === "ai-agents:run-id" && t.Value === "run-1"));
});

test("a retry finds the VM already tagged with this run and claims nothing new", async () => {
  ec2Mock.on(DescribeInstancesCommand).resolves({ Reservations: [{ Instances: [{ InstanceId: "i-mine", Tags: [{ Key: "ai-agents:run-id", Value: "run-1" }, { Key: "ai-agents:size", Value: "full" }] }] }] });
  const vm = await new MockActivityEnvironment().run(acquireSandbox, req);
  assert.equal(vm.instanceId, "i-mine");
  assert.equal(asgMock.commandCalls(SetDesiredCapacityCommand).length, 0);
});

test("when another claim detached the VM first, it takes the next one", async () => {
  ec2Mock.on(DescribeInstancesCommand).resolves({ Reservations: [] });
  asgMock.on(DescribeAutoScalingGroupsCommand).resolvesOnce(group(0)).resolvesOnce(group(0)).resolves(group(2, "i-a", "i-b"));
  asgMock.on(DetachInstancesCommand, { InstanceIds: ["i-a"] })
    .rejects(new AutoScalingServiceException({ name: "ValidationError", message: "not part of the group", $fault: "client", $metadata: {} }));
  const vm = await new MockActivityEnvironment().run(acquireSandbox, req);
  assert.equal(vm.instanceId, "i-b");
});
